def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    cells = [(y, x) for y in range(H) for x in range(W) if g[y, x] != bg]

    def rotated(cy2, cx2, k):
        # positions of all cells rotated k*90 degrees about (cy2/2, cx2/2)
        res = []
        for (y, x) in cells:
            dy, dx = 2 * y - cy2, 2 * x - cx2
            for _ in range(k):
                dy, dx = dx, -dy
            if (dy + cy2) % 2 or (dx + cx2) % 2:
                return None
            ny, nx = (dy + cy2) // 2, (dx + cx2) // 2
            if not (0 <= ny < H and 0 <= nx < W):
                return None
            res.append((ny, nx, g[y, x]))
        return res

    def union(cy2, cx2):
        out = g.copy()
        for k in (1, 2, 3):
            r = rotated(cy2, cx2, k)
            if r is None:
                return None
            for ny, nx, c in r:
                if out[ny, nx] == bg:
                    out[ny, nx] = c
                elif out[ny, nx] != c:
                    return None
        return out

    best = None
    for cy2 in range(2 * H):
        for cx2 in range(2 * W):
            o = union(cy2, cx2)
            if o is not None:
                n = int((o != g).sum())
                if best is None or n < best[0]:
                    best = (n, cy2, cx2)
    if best is None:
        emit(g.copy(), "No consistent rotation centre; output equals input.")
        return g

    _, cy2, cx2 = best
    out = g.copy()
    emit(out.copy(), f"Input; the 4-fold rotation centre is at ({cy2/2}, {cx2/2}), "
                     "the point where the figure is closest to rotational symmetry.")
    names = {1: "90", 2: "180", 3: "270"}
    for k in (1, 2, 3):
        for ny, nx, c in rotated(cy2, cx2, k):
            if out[ny, nx] == bg:
                out[ny, nx] = c
        emit(out.copy(), f"Stamp the figure rotated {names[k]} degrees about the centre.")
    return out
